import Foundation
import SilliesTextModels

/// One completed native session; never share mutable generation state between active turns.
actor AppleConversationSessions {
  typealias Factory =
    @Sendable (TextGenerationRequest, AppleToolInvocation) throws -> any AppleChatSession
  private struct Cached {
    let id: UUID
    let session: any AppleChatSession
    let invocation: AppleToolInvocation
    let continuation: TextConversationContinuation
  }
  private let owner = UUID()
  private let factory: Factory
  private var lifetimes: [UUID: TextModelLifetime] = [:]
  private var cached: Cached?
  private var active = false
  private var epoch = UUID()
  private var retention = TextModelRegistry.Retention.available

  init(factory: @escaping Factory = { try NativeAppleChatSession(request: $0, invocation: $1) }) {
    self.factory = factory
  }

  func retain(for lifetime: TextModelLifetime) async {
    lifetimes[lifetime.id] = lifetime
    let id = lifetime.id
    await lifetime.onEnd(owner: owner) { [weak self] in await self?.end(id) }
  }

  func stop() {
    epoch = UUID()
    cached = nil
    lifetimes.removeAll()
  }
  func setRetention(_ retention: TextModelRegistry.Retention) {
    self.retention = retention
    if retention == .memoryPressure {
      epoch = UUID()
      cached = nil
    }
  }

  func respond(
    _ request: TextGenerationRequest, tools: ConversationToolbox,
    receive: @escaping TextDeltaSink
  ) async throws -> String {
    try Task.checkCancellation()
    guard !active else { throw TextModelError.busy }
    active = true
    defer { active = false }
    let previous = cached
    cached = nil
    let generation = epoch
    let invocation: AppleToolInvocation
    let session: any AppleChatSession
    if let previous, let suffix = previous.continuation.suffix(for: request),
      suffix.count == 1, suffix.first?.role == .user, retention == .available
    {
      invocation = previous.invocation
      session = previous.session
    } else {
      invocation = AppleToolInvocation()
      session = try factory(request, invocation)
    }
    await invocation.open(tools)
    do {
      let answer = try await session.respond(request, receive: receive)
      await invocation.close()
      try Task.checkCancellation()
      // Preserve the framework-owned transcript, including native tool entries. Validate the next
      // request against our exact committed exchanges; do not reconstruct a completed native turn.
      let exchanges = await tools.exchanges
      // A clarification exits native generation through a tool error; its canonical call/result
      // is saved, but the interrupted framework transcript must not be retained for the next turn.
      let awaitsAnswer = await tools.clarification != nil
      if let id = request.sessionID, let lifetime = lifetimes[id], await lifetime.isActive,
        generation == epoch, retention == .available, !awaitsAnswer
      {
        cached = Cached(
          id: id, session: session, invocation: invocation,
          continuation: .init(
            request: request, response: .init(text: answer), completedExchanges: exchanges))
      }
      return answer
    } catch {
      await invocation.close()
      throw error
    }
  }

  private func end(_ id: UUID) {
    lifetimes[id] = nil
    if cached?.id == id { cached = nil }
  }
}

import FoundationModels
import SilliesTextModels

enum AppleConversationTranscript {
  static func make(_ request: TextGenerationRequest, tools: [Transcript.ToolDefinition] = []) throws
    -> Transcript
  {
    guard request.messages.last?.role == .user else { throw TextModelError.invalidResponse }
    var entries: [Transcript.Entry] = [
      .instructions(
        .init(segments: [.text(.init(content: request.instructions))], toolDefinitions: tools))
    ]
    for message in request.messages.dropLast() {
      let segments: [Transcript.Segment] = [.text(.init(content: message.content))]
      switch message.role {
      case .user: entries.append(.prompt(.init(segments: segments)))
      case .assistant:
        if !message.content.isEmpty {
          entries.append(.response(.init(assetIDs: [], segments: segments)))
        }
        if !message.calls.isEmpty {
          entries.append(
            .toolCalls(
              .init(
                try message.calls.map {
                  .init(
                    id: $0.id, toolName: $0.name,
                    arguments: try GeneratedContent(
                      json: String(decoding: $0.arguments, as: UTF8.self)))
                })))
        }
      case .tool:
        guard let id = message.callID, let name = message.toolName else {
          throw TextModelError.invalidResponse
        }
        entries.append(.toolOutput(.init(id: id, toolName: name, segments: segments)))
      }
    }
    return Transcript(entries: entries)
  }
}

import Foundation
import FoundationModels
import SilliesCore

struct AppleConversationTool: Tool {
  typealias Arguments = GeneratedContent
  let name: String
  let description: String
  let parameters: GenerationSchema
  private let invoke: @Sendable (ConversationToolCall) async throws -> String

  init(_ definition: ConversationToolDefinition, toolbox: ConversationToolbox) throws {
    try self.init(definition, invoke: toolbox.invoke)
  }

  init(
    _ definition: ConversationToolDefinition,
    invoke: @escaping @Sendable (ConversationToolCall) async throws -> String
  ) throws {
    name = definition.name
    description = definition.description
    self.invoke = invoke
    parameters = try GenerationSchema(
      root: DynamicGenerationSchema(
        name: definition.name + "Arguments",
        properties: definition.parameters.map {
          DynamicGenerationSchema.Property(
            name: $0.name, description: $0.description, schema: Self.schema($0),
            isOptional: $0.requirement == .optional)
        }), dependencies: [])
  }
  private static func schema(_ parameter: ConversationToolDefinition.Parameter)
    -> DynamicGenerationSchema
  {
    switch parameter.kind {
    case .string: DynamicGenerationSchema(type: String.self)
    case .integer: DynamicGenerationSchema(type: Int.self)
    case .boolean: DynamicGenerationSchema(type: Bool.self)
    case .choice(let choices): DynamicGenerationSchema(name: parameter.name, anyOf: choices)
    }
  }
  func call(arguments: GeneratedContent) async throws -> String {
    try await invoke(
      .init(id: UUID().uuidString, name: name, arguments: Data(arguments.jsonString.utf8)))
  }
}

